<script>(function(){var body=document.getElementById('recharge-rows'),tpl=document.getElementById('recharge-row-template'),add=document.getElementById('add-recharge-row'),operator=document.getElementById('recharge-operator'),agencyGroups=@json($advertisingAgencyGroups),history=@json($accountHistoryMatches);if(operator)operator.addEventListener('change',function(){window.location.href=this.dataset.url+'?operator_user_id='+encodeURIComponent(this.value);});function key(v){return(v||'').trim().toLowerCase();}function names(){Array.prototype.forEach.call(body.rows,function(row,i){row.querySelector('.agency-select').name='entries['+i+'][agency_id]';row.querySelector('.account-name').name='entries['+i+'][account_name]';row.querySelector('.account-number').name='entries['+i+'][account_number]';row.querySelector('.amount').name='entries['+i+'][amount]';});}function validate(row){var agency=row.querySelector('.agency-select').value,name=row.querySelector('.account-name'),number=row.querySelector('.account-number'),hint=row.querySelector('.account-match-hint'),match=history[agency]||{by_number:{}},names=match.by_number[key(number.value)]||[],message='',hintText=names.length?'系统记录：'+names.join('、')+'（编号 '+number.value.trim()+'）':'';if(name.value.trim()&&number.value.trim()&&names.length&&!names.some(function(v){return key(v)===key(name.value);})){message='账户名称与系统历史记录不一致，正确名称：'+names.join('、');}name.setCustomValidity(message);hint.textContent=hintText;hint.classList.toggle('has-error',!!message);hint.classList.toggle('has-history',!message&&!!hintText);row.querySelector('.account-name-cell').classList.toggle('account-match-error',!!message);return!message;}function append(){body.appendChild(tpl.content.cloneNode(true));names();}function fillMedia(row,agencyName){var media=row.querySelector('.agency-select'),options=agencyGroups[agencyName]||[];media.innerHTML='<option value="">请选择广告社媒</option>';options.forEach(function(item){var option=document.createElement('option');option.value=item.key;option.textContent=item.media;media.appendChild(option);});media.disabled=options.length===0;validate(row);}add.addEventListener('click',append);body.addEventListener('change',function(e){var row=e.target.closest('tr');if(e.target.classList.contains('agency-name-select'))fillMedia(row,e.target.value);if(e.target.classList.contains('agency-select'))validate(row);});body.addEventListener('input',function(e){if(e.target.classList.contains('account-name')||e.target.classList.contains('account-number'))validate(e.target.closest('tr'));});body.closest('form').addEventListener('submit',function(e){var valid=true;Array.prototype.forEach.call(body.rows,function(row){if(!validate(row))valid=false;});if(!valid){e.preventDefault();var invalid=body.querySelector(':invalid');if(invalid)invalid.reportValidity();}});append();})();</script>
